foods, md = [], ['# هيرو · نسخة 108 · أكلات جديدة للمراجعة', '',
 'القيم لكل 100 غم من الناتج الجاهز. تنحسب من المكوّنات (أوزان بالغرام قبل الطبخ حسب قاعدة هيرو) مقسومة على وزن الناتج. كلها **تقديرية (E)** لأن الوصفات تختلف بين بيت وبيت؛ غيّر الأوزان إذا وصفتكم تختلف وأعد تشغيل `python3 src108/recipes108.py`.', '',
 '| الأكلة | المكوّنات (غم) | الناتج غم | سعرات | بروتين | كارب | دهن |', '|---|---|---|---|---|---|---|']
names = set(DB)
for name, en, cat, items, y, meas, piece, syn in R:
    if name in names: sys.exit('✗ موجودة من قبل: ' + name)
    t = [sum(ing(n)[i] * g / 100 for n, g in items) for i in range(4)]
    v = [round(x / y * 100, 1) for x in t]
    foods.append({'name': name, 'en': en, 'cat': cat, 'cal': round(v[0]), 'pro': v[1], 'carb': v[2], 'fat': v[3], 'src': 'E', 'piece': piece, 'meas': meas, 'syn': syn})
    md.append(f"| {name} | {'، '.join(f'{n} {g}' for n, g in items)} | {y} | {round(v[0])} | {v[1]} | {v[2]} | {v[3]} |")
for name, en, cat, c, p, cb, f, src, meas, piece in D:
    if name in names: sys.exit('✗ موجودة من قبل: ' + name)
    foods.append({'name': name, 'en': en, 'cat': cat, 'cal': c, 'pro': p, 'carb': cb, 'fat': f, 'src': src, 'piece': piece, 'meas': meas, 'syn': None})
    md.append(f"| {name} | (قيمة مباشرة {'USDA' if src=='U' else 'تقديرية'}) | 100 | {c} | {p} | {cb} | {f} |")
assert len({f['name'] for f in foods}) == len(foods)
json.dump(foods, open(os.path.join(ROOT, 'src108', 'foods108.json'), 'w', encoding='utf-8', newline='\n'), ensure_ascii=False, indent=1)
open(os.path.join(ROOT, 'src108', 'RECIPES108.md'), 'w', encoding='utf-8', newline='\n').write('\n'.join(md) + '\n')
print(len(foods), 'أكلة')
